rule.definition:
a!localVariables(
  local!nominationInstance:
  index(
    ri!nomination,
    wherecontains(
      tointeger(property(ri!interview,"nominationId",null)),
      tointeger(property(ri!nomination,"nominationId",null))
    ),
    null
  ),

  if(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!nominationInstance),
    null,
    if(
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4717821" = #"_a-0000e790-a118-8000-9c1b-011c48011c48_5604382",
      concat(
        ri!subject,
        " - ",
        property(local!nominationInstance,"lastName",null),
        ", ",
        property(local!nominationInstance,"firstName",null),
        if(
          #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(property(local!nominationInstance,"middleName",null)),
          null,
          if(
            len(property(local!nominationInstance,"middleName",null))>0,
            " " & left(property(local!nominationInstance,"middleName",null),1),
            null
          )
        )
      ),
      concat(
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4717821",
        " : ",
        ri!subject,
        " - ",
        property(local!nominationInstance,"lastName",null),
        ", ",
        property(local!nominationInstance,"firstName",null),
        if(
          #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(property(local!nominationInstance,"middleName",null)),
          null,
          if(
            len(property(local!nominationInstance,"middleName",null))>0,
            " " & left(property(local!nominationInstance,"middleName",null),1),
            null
          )
        )
      )
    )
  )
)
